# ---------------------------------------------------------------------------
# Verification of the exported image files
# ---------------------------------------------------------------------------

import os
import re
from collections.abc import Mapping
from io import BytesIO
from typing import Any

from PIL import Image

DEFAULT_OUTPUT_DIRS = ("$HOME/Downloads", "/home/user/Downloads", "$HOME/Desktop")
_DIRECTORY_KEYS = ("download_dir", "download_dirs", "output_dir", "output_dirs", "search_dirs")
_HEX_DIGEST = re.compile(r"^[0-9a-f]{64}$")


def _expand(raw: Any) -> str:
    """Return a path with ``~`` and environment variables expanded."""
    return str(Path(os.path.expandvars(os.path.expanduser(str(raw)))))


def _declared_directories(params: Mapping[str, Any], recipes: list) -> list:
    """Return the directories that are searched for the exported files."""
    found: list = []
    for name in _DIRECTORY_KEYS:
        value = params.get(name)
        values = value if isinstance(value, (list, tuple)) else [value]
        for item in values:
            if isinstance(item, str) and item:
                path = _expand(item)
                if path not in found:
                    found.append(path)
    for recipe in recipes:
        if not isinstance(recipe, Mapping):
            continue
        for name in ("output_path", "output_dir"):
            value = recipe.get(name)
            if isinstance(value, str) and value:
                path = _expand(str(Path(value).parent))
                if path not in found:
                    found.append(path)
    for raw in DEFAULT_OUTPUT_DIRS:
        path = _expand(raw)
        if path not in found:
            found.append(path)
    return found


def _name_variants(output_name: str) -> list:
    """Return the declared name and the numbered names a browser download uses."""
    stem, extension = os.path.splitext(output_name)
    names = [output_name]
    for index in range(1, 10):
        names.append("%s (%d)%s" % (stem, index, extension))
    return names


def _read_bytes(controller: Any, path: str) -> tuple:
    """Return ``(payload, problem)`` for one path; the payload is ``None`` when absent."""
    try:
        candidate = Path(path)
        if candidate.is_file():
            return candidate.read_bytes(), ""
    except OSError as exc:
        return None, "%s: %s" % (type(exc).__name__, exc)
    getter = getattr(controller, "get_file", None)
    if callable(getter):
        try:
            payload = getter(path)
        except Exception as exc:
            return None, "%s: %s" % (type(exc).__name__, exc)
        if isinstance(payload, (bytes, bytearray)) and payload:
            return bytes(payload), ""
        return None, "the file could not be read"
    return None, "the file is absent"


def _pixel_digest(image: Image.Image) -> str:
    """Return the SHA-256 digest of the decoded RGBA pixels."""
    return hashlib.sha256(image.convert("RGBA").tobytes()).hexdigest()


def _inspect(controller: Any, path: str) -> dict:
    """Return the observed properties of one candidate export file."""
    entry = {"path": path, "bytes": None, "format": None, "size": None, "pixel_sha256": None, "problem": ""}
    payload, problem = _read_bytes(controller, path)
    if payload is None:
        entry["problem"] = problem
        return entry
    entry["bytes"] = len(payload)
    try:
        with Image.open(BytesIO(payload)) as image:
            image.load()
            entry["format"] = str(image.format or "").upper()
            entry["size"] = [image.width, image.height]
            entry["pixel_sha256"] = _pixel_digest(image)
    except Exception as exc:
        entry["problem"] = "%s: %s" % (type(exc).__name__, exc)
    return entry


def _check_export(controller: Any, recipe: Mapping[str, Any], directories: list) -> dict:
    """Compare one declared output file with its declared pixel signature."""
    output_name = str(recipe.get("output_name") or "")
    expected_size = [int(value) for value in recipe.get("size") or []]
    expected_digest = str(recipe.get("pixel_sha256") or "")
    expected = {"output_name": output_name, "size": expected_size, "pixel_sha256": expected_digest}
    candidates: list = []
    for directory in directories:
        for name in _name_variants(output_name):
            path = str(Path(directory) / name)
            if path not in candidates:
                candidates.append(path)
    observed: list = []
    for path in candidates:
        entry = _inspect(controller, path)
        if entry["bytes"] is None:
            continue
        observed.append(entry)
        if entry["format"] != "PNG":
            continue
        if entry["size"] != expected_size:
            continue
        if entry["pixel_sha256"] != expected_digest:
            continue
        return {
            "check_id": output_name,
            "output_name": output_name,
            "passed": True,
            "expected": expected,
            "observed": observed,
            "matched_path": path,
            "problem": "",
        }
    problem = "the file is absent"
    if observed:
        problem = "no file matches the declared pixel signature"
    return {
        "check_id": output_name,
        "output_name": output_name,
        "passed": False,
        "expected": expected,
        "observed": observed,
        "matched_path": None,
        "problem": problem,
    }


def _recipe_problem(recipe: Any) -> str:
    """Return why a declared recipe cannot be judged, or an empty string."""
    if not isinstance(recipe, Mapping):
        return "a declared recipe is not a mapping"
    if not str(recipe.get("output_name") or ""):
        return "a declared recipe has no output name"
    size = recipe.get("size")
    if not isinstance(size, list) or len(size) != 2 or not all(isinstance(value, int) for value in size):
        return "a declared recipe has no pixel dimensions"
    if not _HEX_DIGEST.match(str(recipe.get("pixel_sha256") or "")):
        return "a declared recipe has no pixel digest"
    return ""


class OpenPhotoEdit2Evaluator(BaseEvaluator):
    """Verify the exported PNG files against their declared pixel signatures."""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        if params.get("expected_instruction_sha256") not in (None, INSTRUCTION_SHA256):
            return EvalResult(EvalStatus.ERROR, "instruction binding mismatch", {"read_only": True})
        if params.get("expected_ruleset_sha256") not in (None, RULESET_SHA256):
            return EvalResult(EvalStatus.ERROR, "ruleset binding mismatch", {"read_only": True})
        declared_task = params.get("expected_task_id")
        if declared_task is not None and declared_task != TASK_ID:
            return EvalResult(EvalStatus.ERROR, "task binding mismatch", {"read_only": True})
        recipes = RULESET_SPEC.get("recipes")
        if not isinstance(recipes, list) or not recipes:
            return EvalResult(EvalStatus.ERROR, "the ruleset declares no export recipes", {"read_only": True})
        for recipe in recipes:
            problem = _recipe_problem(recipe)
            if problem:
                return EvalResult(EvalStatus.ERROR, "the ruleset is malformed: " + problem, {"read_only": True})
        directories = _declared_directories(params, recipes)
        controller = context.get("controller")
        checks = [_check_export(controller, recipe, directories) for recipe in recipes]
        failures = [check["check_id"] for check in checks if not check["passed"]]
        metadata = {
            "task_id": TASK_ID,
            "evaluator_id": EVALUATOR_ID,
            "instruction_sha256": INSTRUCTION_SHA256,
            "ruleset_sha256": RULESET_SHA256,
            "read_only": True,
            "searched_directories": directories,
            "checks": checks,
            "failures": failures,
        }
        if failures:
            return EvalResult(
                EvalStatus.FAIL,
                "exported files do not match the declared pixel signatures: " + ", ".join(failures),
                metadata,
            )
        return EvalResult(EvalStatus.PASS, "every declared export matches its declared pixel signature", metadata)
